package dev.chyken.assembl_ar.workflow.phase;

import org.junit.Test;
import static org.junit.Assert.*;
import dev.chyken.assembl_ar.workflow.phase.Phase8SensorWiringFlow.Screen;
import dev.chyken.assembl_ar.model.*;
import dev.chyken.assembl_ar.model.ComponentWiringColorConfig.Wire;

public final class Phase8SensorWiringFlowTest {
    @Test public void onlyTwoScreensCanEverRequestCameraFrames(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);for(Screen s:Screen.values()){f.devJump(s.ordinal()+1,20);assertEquals(s.scan(),f.scanning());assertFalse(s.video()&&f.scanning());}}
    @Test public void demoDoesNotUnlockUntilExplicitConfirmation(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);f.devJump(3,20);assertFalse(f.next(30));assertFalse(f.accepts(f.tag(),40));f.observe(true);assertFalse(f.complete());f.confirm();assertTrue(f.next(50));assertEquals(Screen.MOUNT_SCAN,f.screen());assertTrue(f.previous(60));assertEquals(Screen.MOUNT_DEMO,f.screen());assertFalse(f.scanning());}
    @Test public void previousNeverInfersItsDestinationFromPlayback(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);for(int i=14;i>1;i--){f.devJump(i,20+i);assertTrue(f.previous(100+i));assertEquals(i-1,f.step());}}
    @Test public void scanRejectsStaleDuplicateAndOtherStageEvidence(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);Object old=f.tag();assertFalse(f.accepts(old,9));assertTrue(f.accepts(old,11));assertFalse(f.accepts(old,11));f.observe(true);assertFalse(f.complete());f.observe(false);f.observe(true);assertFalse(f.complete());f.observe(true);assertTrue(f.complete());f.devJump(4,30);assertFalse(f.accepts(old,50));f.pause();assertFalse(f.accepts(f.tag(),60));f.resume(100);assertFalse(f.accepts(f.tag(),90));}
    @Test public void rescanOnlyResetsSelectedGateAndRetainsColors(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);f.devComplete();f.devJump(4,20);ComponentWiringColorConfig c=f.colors();f.rescan(30);assertFalse(f.complete());assertTrue(f.scanning());f.devJump(1,40);assertTrue(f.complete());f.devJump(14,50);assertTrue(f.complete());assertEquals(c,f.colors());assertFalse(f.canFinish(false));}
    @Test public void preparationAndPickerAreExplicitSeparateGates(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);f.devJump(5,20);assertFalse(f.next(30));f.confirm();assertTrue(f.next(40));assertEquals(Screen.DISTANCE_COLORS,f.screen());f.applyColors(f.colors().with(Wire.TRIGGER,MotorWireColorConfig.Swatch.ORANGE),50);assertEquals(Screen.DISTANCE_WIRING,f.screen());assertFalse(f.complete());assertEquals(MotorWireColorConfig.Swatch.ORANGE.argb,f.colors().triggerWireColor);}
    @Test public void everyScreenAndColorSurvivesProcessRecreation(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);f.devComplete();for(int i=1;i<=14;i++){f.devJump(i,100);Phase8SensorWiringFlow restored=Phase8SensorWiringFlow.restore(f.snapshot(),200);assertEquals(i,restored.step());assertEquals(f.snapshot(),restored.snapshot());assertFalse(restored.scanning());}}
    @Test public void oldMountCompletionMigratesToWiringPreparation(){Phase8SensorWiringFlow f=Phase8SensorWiringFlow.restore("legacyMount",10);assertEquals(Screen.DISTANCE_PREP,f.screen());assertFalse(f.complete());assertFalse(f.canFinish(false));assertEquals(AssemblyPhaseCatalog.DISTANCE_SENSOR_MOUNT,new PhaseSessionCheckpoint(AssemblyPhaseCatalog.SENSOR_WIRING,false,PhaseFlow.Mode.DEMO,0,0,true,false,null).phaseId);}
    @Test public void noPartialOrMalformedSnapshotCanFinishPhase(){for(String bad:new String[]{null,"","1:14,1111111111111,x","1:99,11111111111111,x","garbage"}){Phase8SensorWiringFlow f=Phase8SensorWiringFlow.restore(bad,10);assertEquals(1,f.step());assertFalse(f.canFinish(false));}}
    @Test public void finalCheckRequiresEveryGateForNormalAssembly(){Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);f.devJump(14,20);f.confirm();assertFalse(f.canFinish(false));assertTrue(f.canFinish(true));f.devComplete();assertTrue(f.canFinish(false));assertEquals(PhaseFlow.Mode.COMPLETE,f.mode());}
    @Test public void rootFlowDelegatesEvidenceAndCheckpointOwnership(){PhaseFlow root=new PhaseFlow(AssemblyPhaseCatalog.byId(AssemblyPhaseCatalog.DISTANCE_SENSOR_MOUNT),0,false);Phase8SensorWiringFlow f=new Phase8SensorWiringFlow(10);root.attachSensorWiringFlow(f);assertEquals(f.tag(),root.tag());assertTrue(root.collectsEvidence());root.interrupt(50);assertFalse(root.collectsEvidence());root.resume(100);assertTrue(root.collectsEvidence());f.devJump(3,110);assertFalse(root.collectsEvidence());assertFalse(root.canScan());}
}
